1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export interface InsuredItem {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface Step {
28	  op: string;
29	  items?: InsuredItem[];
30	  policy?: number;
31	  incident?: Incident;
32	}
33	
34	export interface QuoteResult {
35	  premium: number;
36	}
37	
38	export interface ClaimResult {
39	  payout: number;
40	  remainingCap: number;
41	}
42	
43	export type StepResult = QuoteResult | ClaimResult;
44	
45	export interface ScenarioResults {
46	  results: StepResult[];
47	}
48	
49	const BASE_PREMIUMS: Record<string, number> = {
50	  sword: 100,
51	  amulet: 60,
52	  staff: 80,
53	  potion: 40,
54	  rune: 25,
55	  moonstone: 25,
56	};
57	
58	const INSURANCE_VALUES: Record<string, number> = {
59	  sword: 1000,
60	  amulet: 600,
61	  staff: 800,
62	  potion: 400,
63	  rune: 250,
64	  moonstone: 250,
65	};
66	
67	const PROCESSING_FEE = 5;
68	
69	const WHOLE_PERCENT = 100;
70	
71	/**
72	 * Adjusts an amount by a percentage. A positive percent is a surcharge, a
73	 * negative one a discount.
74	 *
75	 * Multiplying before dividing keeps the arithmetic exact. A 1.1 multiplier
76	 * would not: floating-point `100 * 1.1` is 110.00000000000001, which rounds
77	 * up to 111 and yields a 116 G premium instead of 115 G.
78	 */
79	const adjustByPercent = (amount: number, percent: number): number =>
80	  (amount * (WHOLE_PERCENT + percent)) / WHOLE_PERCENT;
81	
82	/** All rounding is in the MHPCO's favor — always up. */
83	const roundInMHPCOsFavor = Math.ceil;
84	
85	const BUILDING_BLOCK_SIZE = 3;
86	const BUILDING_BLOCK_PREMIUM = 60;
87	
88	/** Only items of one and the same kind group into a block. */
89	const areAllTheSameKind = ([first, ...rest]: InsuredItem[]): boolean =>
90	  first !== undefined && rest.every((item) => item.type === first.type);
91	
92	/**
93	 * How many flat-rate blocks this list forms. A mixed list forms none — only
94	 * alike items group — and so does any list too short to fill one block.
95	 */
96	const countCompleteBlocks = (items: InsuredItem[]): number =>
97	  areAllTheSameKind(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
98	
99	const CURSED_SURCHARGE_PERCENT = 50;
100	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
101	const HIGH_ENCHANTMENT_LEVEL = 5;
102	
103	/** A risk rule contributes its percent only when the item trips it. */
104	const percentWhen = (applies: boolean, percent: number): number =>
105	  applies ? percent : 0;
106	
107	const isHighlyEnchanted = (item: InsuredItem): boolean =>
108	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
109	
110	/** Risk surcharges add to the base premium; they do not compound. */
111	const riskSurchargePercentFor = (item: InsuredItem): number =>
112	  percentWhen(item.cursed === true, CURSED_SURCHARGE_PERCENT) +
113	  percentWhen(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
114	
115	/** An item's list price with its own risk surcharges applied. */
116	const riskAdjustedPremiumFor = (item: InsuredItem): number =>
117	  adjustByPercent(BASE_PREMIUMS[item.type], riskSurchargePercentFor(item));
118	
119	/**
120	 * Prices an item list: alike items are grouped into building blocks sold at a
121	 * flat rate, and whatever is left over is priced item by item, each at its own
122	 * risk-adjusted premium.
123	 */
124	const priceItems = (items: InsuredItem[]): number => {
125	  const blocks = countCompleteBlocks(items);
126	  const leftovers = items.slice(blocks * BUILDING_BLOCK_SIZE);
127	
128	  return (
129	    blocks * BUILDING_BLOCK_PREMIUM +
130	    leftovers.reduce((sum, item) => sum + riskAdjustedPremiumFor(item), 0)
131	  );
132	};
133	
134	/** Discounts are negative adjustments — long-standing customers pay 20% less. */
135	const LOYALTY_DISCOUNT_PERCENT = -20;
136	const LOYALTY_YEARS = 2;
137	const REPEAT_CONTRACT_DISCOUNT_PERCENT = -15;
138	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
139	
140	const isLongStanding = (customer: Customer): boolean =>
141	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
142	
143	/** The first contract is assessed; every later one earns a discount instead. */
144	const contractPercentFor = (isFirstContract: boolean): number =>
145	  isFirstContract
146	    ? FIRST_INSURANCE_SURCHARGE_PERCENT
147	    : REPEAT_CONTRACT_DISCOUNT_PERCENT;
148	
149	/**
150	 * The customer's own standing modifies the item price. Unlike the risk
151	 * surcharges, which add up before being applied once, these modifiers
152	 * COMPOUND: each applies to the result of the last. A 20% discount followed
153	 * by a 10% surcharge is 100 -> 80 -> 88, not 100 -> 90.
154	 */
155	const applyCustomerModifiers = (
156	  price: number,
157	  customer: Customer,
158	  isFirstContract: boolean,
159	): number => {
160	  const afterLoyalty = adjustByPercent(
161	    price,
162	    percentWhen(isLongStanding(customer), LOYALTY_DISCOUNT_PERCENT),
163	  );
164	
165	  return adjustByPercent(afterLoyalty, contractPercentFor(isFirstContract));
166	};
167	
168	/**
169	 * The premium pipeline, in the order the spec states it: price the items,
170	 * apply the customer's modifiers, round, then add the processing fee last.
171	 */
172	const quotePremium = (
173	  items: InsuredItem[],
174	  customer: Customer,
175	  isFirstContract: boolean,
176	): QuoteResult => ({
177	  premium:
178	    roundInMHPCOsFavor(
179	      applyCustomerModifiers(priceItems(items), customer, isFirstContract),
180	    ) + PROCESSING_FEE,
181	});
182	
183	/**
184	 * Every step is a quote today, so the first step is also the first contract.
185	 * Once claims interleave with quotes, the Nth step stops being the Nth
186	 * contract and this is the line that has to learn to count quotes instead.
187	 */
188	const isFirstContractAtStep = (stepIndex: number): boolean => stepIndex === 0;
189	
190	const DEDUCTIBLE = 100;
191	const CAP_MULTIPLE = 2;
192	
193	const insuranceSumOf = (items: InsuredItem[]): number =>
194	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
195	
196	const settleClaim = (incident: Incident, insuredItems: InsuredItem[]): ClaimResult => {
197	  const damage = incident.damages.reduce((sum, d) => sum + d.amount, 0);
198	  const payout = Math.max(0, damage - DEDUCTIBLE);
199	
200	  return {
201	    payout,
202	    remainingCap: CAP_MULTIPLE * insuranceSumOf(insuredItems) - payout,
203	  };
204	};
205	
206	export const runScenario = (scenario: Scenario): ScenarioResults => ({
207	  results: scenario.steps.map((step, stepIndex) => {
208	    if (step.op === "claim") {
209	      const policy = scenario.steps[step.policy ?? 0];
210	
211	      return settleClaim(step.incident!, policy.items ?? []);
212	    }
213	
214	    return quotePremium(
215	      step.items ?? [],
216	      scenario.customer,
217	      isFirstContractAtStep(stepIndex),
218	    );
219	  }),
220	});
