};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step, stepIndex) => {
    if (step.op === "claim") {
      const policy = scenario.steps[step.policy ?? 0];

      return settleClaim(step.incident!, policy.items ?? []);
    }

    return quotePremium(
      step.items ?? [],
      scenario.customer,
      isFirstContractAtStep(stepIndex),
    );
  }),
});

