/** One incident is one deductible, so the damages are totalled before it applies. */
const totalDamageOf = (incident: Incident): number =>
  incident.damages.reduce((sum, damage) => sum + damage.amount, 0);

/** The MHPCO never pays a negative claim; below the deductible it pays nothing. */
const NO_PAYOUT = 0;

const settleClaim = (
  incident: Incident,
  insuredItems: InsuredItem[],
): ClaimResult => {
  const payout = Math.max(NO_PAYOUT, totalDamageOf(incident) - DEDUCTIBLE);

  return {
    payout,
    remainingCap: CAP_MULTIPLE * insuranceSumOf(insuredItems) - payout,
  };
};

/**
 * A claim names the quote step it is made against; the items on that step are
 * the ones the policy covers.
 */
const itemsCoveredBy = (claim: ClaimStep, steps: Step[]): InsuredItem[] => {
  const policy = steps[claim.policy];

  return policy.op === "quote" ? policy.items : [];
};

export const runScenario = ({
  customer,
  steps,
}: Scenario): ScenarioResults => ({
  results: steps.map((step, stepIndex) =>
    step.op === "claim"
      ? settleClaim(step.incident, itemsCoveredBy(step, steps))
      : quotePremium(step.items, customer, isFirstContractAtStep(stepIndex)),
  ),
});
